#!/bin/bash
set -e
cd avbox

echo "=== 替换应用图标为 Hello（含 round） ==="

echo "" | base64 -d > app/src/main/res/mipmap-mdpi/ic_launcher.webp
echo "" | base64 -d > app/src/main/res/mipmap-mdpi/ic_launcher_round.webp
echo "" | base64 -d > app/src/main/res/mipmap-hdpi/ic_launcher.webp
echo "" | base64 -d > app/src/main/res/mipmap-hdpi/ic_launcher_round.webp
echo "" | base64 -d > app/src/main/res/mipmap-xhdpi/ic_launcher.webp
echo "" | base64 -d > app/src/main/res/mipmap-xhdpi/ic_launcher_round.webp
echo "" | base64 -d > app/src/main/res/mipmap-xxhdpi/ic_launcher.webp
echo "" | base64 -d > app/src/main/res/mipmap-xxhdpi/ic_launcher_round.webp
echo "" | base64 -d > app/src/main/res/mipmap-xxxhdpi/ic_launcher.webp
echo "" | base64 -d > app/src/main/res/mipmap-xxxhdpi/ic_launcher_round.webp
echo "" | base64 -d > app/src/main/res/drawable/ic_launcher_foreground.webp

echo "应用图标已替换为 Hello（含 round）"

echo "=== 应用图标替换完成 ==="